<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Document\TemplateVersion\Domain\ValueObject\Holder\TemplateVersionContentHtmlAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TemplateVersionContentHtmlAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TemplateVersionContentHtmlAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getContentHtml returns null on a freshly created holder.
     */
    public function testContentHtmlNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTemplateVersionContentHtmlAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isContentHtmlAssigned());
        $this->assertNull($holder->getContentHtml());
    }
}
class ImplWithTemplateVersionContentHtmlAttributeHolderUnitTest
{
    use TemplateVersionContentHtmlAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedContentHtmlRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultContentHtml();
    }
}
